  /* ---------------- reading & listening texts ---------------- */
  const texts = [
    { id: 'fr-t-a1-presentation', l: 'A1', title: 'Je m\'appelle Camille', assess: 'reading', text: 'Bonjour ! Je m\'appelle Camille, j\'ai trente et un ans. Je suis infirmière à l\'hôpital de Lyon. J\'habite dans un petit appartement près de la gare. Je travaille souvent la nuit et le week-end. Le dimanche, je vais au marché avec mon frère et le soir, je regarde un film.',
      qs: [{ q: 'Quelle est la profession de Camille ?', o: ['Médecin', 'Infirmière', 'Professeure'], a: 1 }, { q: 'Que fait-elle le dimanche ?', o: ['Elle travaille.', 'Elle va au marché avec son frère.', 'Elle va à la gare.'], a: 1 }] },
    { id: 'fr-t-a1-boulangerie', l: 'A1', title: 'À la boulangerie', assess: 'listening', kind: 'dialogue', text: 'Bonjour madame ! — Bonjour monsieur, une baguette et deux croissants, s\'il vous plaît. — Et avec ceci ? — C\'est tout, merci. Ça fait combien ? — Trois euros quarante. — Voilà. — Merci, bonne journée !',
      qs: [{ q: 'Qu\'est-ce que la cliente achète ?', o: ['Deux baguettes', 'Une baguette et deux croissants', 'Trois croissants'], a: 1 }, { q: 'Combien ça coûte ?', o: ['3,40 €', '4,30 €', '13,40 €'], a: 0 }] },
    { id: 'fr-t-a2-demenagement', l: 'A2', title: 'Un nouveau poste à Genève', assess: 'reading', text: 'Le mois dernier, Marco a quitté Bologne pour Genève. Il a trouvé un poste de médecin dans une clinique privée. Au début, c\'était difficile : il ne connaissait personne et il ne comprenait pas toujours ses collègues suisses, qui disent "septante" et "nonante". Maintenant, il a un appartement au bord du lac et il va au travail à vélo.',
      qs: [{ q: 'Pourquoi Marco est-il parti à Genève ?', o: ['Pour ses études', 'Pour un poste de médecin', 'Pour sa famille'], a: 1 }, { q: 'Qu\'est-ce qui était difficile au début ?', o: ['Il n\'avait pas de vélo.', 'Il ne connaissait personne.', 'La clinique était loin.'], a: 1 }] },
    { id: 'fr-t-a2-repondeur', l: 'A2', title: 'Un message sur le répondeur', assess: 'listening', text: 'Bonjour, ici le cabinet du docteur Lefèvre. Nous vous appelons au sujet de votre rendez-vous de mercredi à dix heures. Malheureusement, le docteur est absent ce jour-là. Pouvez-vous venir vendredi à quatorze heures trente ? Merci de nous rappeler au 04 78 22 31 50. Bonne journée.',
      qs: [{ q: 'Pourquoi le cabinet appelle-t-il ?', o: ['Pour changer le rendez-vous', 'Pour envoyer une facture', 'Pour confirmer une ordonnance'], a: 0 }, { q: 'Quand est le nouveau rendez-vous ?', o: ['Mercredi à 10 h', 'Vendredi à 14 h 30', 'Vendredi à 10 h'], a: 1 }] },
    { id: 'fr-t-b1-sommeil', l: 'B1', title: 'Le travail de nuit et la santé', assess: 'reading', text: 'En France, environ quatre millions de personnes travaillent régulièrement la nuit, notamment dans les hôpitaux, les transports et l\'industrie. Selon plusieurs études, le travail de nuit perturbe l\'horloge biologique : les travailleurs dorment moins et moins bien pendant la journée. À long terme, le risque de maladies cardiovasculaires et de surpoids augmente. Les spécialistes recommandent donc d\'organiser les horaires "dans le sens des aiguilles d\'une montre" — matin, puis après-midi, puis nuit — et de prévoir au moins deux jours de repos après une série de nuits.',
      qs: [{ q: 'Que perturbe le travail de nuit ?', o: ['La digestion uniquement', 'L\'horloge biologique', 'La vue'], a: 1 }, { q: 'Que recommandent les spécialistes ?', o: ['Travailler uniquement la nuit', 'Organiser les horaires matin → après-midi → nuit', 'Boire plus de café'], a: 1 }, { q: 'Combien de jours de repos après les nuits ?', o: ['Au moins un', 'Au moins deux', 'Aucun'], a: 1 }] },
    { id: 'fr-t-b1-teletravail', l: 'B1', title: 'Le télétravail', assess: 'listening', text: 'Depuis la crise sanitaire, beaucoup de salariés travaillent au moins un ou deux jours par semaine à la maison. Ils apprécient de gagner du temps dans les transports et d\'être plus flexibles. D\'autres, en revanche, se sentent isolés et ont du mal à séparer vie professionnelle et vie privée. Beaucoup d\'entreprises ont donc choisi un modèle hybride : trois jours au bureau, deux jours en télétravail.',
      qs: [{ q: 'Quel avantage est cité ?', o: ['Plus de contacts', 'Gagner du temps dans les transports', 'Un bureau plus grand'], a: 1 }, { q: 'Qu\'est-ce que le modèle hybride ?', o: ['Uniquement au bureau', 'Uniquement à la maison', 'Une partie au bureau, une partie à la maison'], a: 2 }] },
    { id: 'fr-t-b2-antibiotiques', l: 'B2', title: 'L\'antibiorésistance', assess: 'reading', d: 'medical', text: 'L\'antibiorésistance est aujourd\'hui considérée comme l\'une des principales menaces pour la santé mondiale. Chaque fois qu\'un antibiotique est utilisé, les bactéries naturellement résistantes survivent et se multiplient. Le phénomène est aggravé par les prescriptions inutiles — par exemple pour des infections virales — et par l\'usage massif d\'antibiotiques dans l\'élevage. C\'est pourquoi de nombreux hôpitaux ont mis en place des équipes de bon usage des antibiotiques, chargées de conseiller les services afin que les traitements soient ciblés, bien dosés et aussi courts que possible.',
      qs: [{ q: 'Comment apparaissent les résistances ?', o: ['Les bactéries résistantes survivent et se multiplient', 'Les virus mutent', 'Les antibiotiques sont trop chers'], a: 0 }, { q: 'Qu\'est-ce qui aggrave le phénomène ?', o: ['Les vaccins', 'Les prescriptions inutiles et l\'élevage', 'Le lavage des mains'], a: 1 }, { q: 'Quel est le rôle des équipes de bon usage ?', o: ['Prescrire plus d\'antibiotiques', 'Conseiller pour des traitements ciblés et courts', 'Fabriquer de nouveaux médicaments'], a: 1 }] },
    { id: 'fr-t-b2-semaine-4j', l: 'B2', title: 'La semaine de quatre jours', assess: 'listening', text: 'Plusieurs entreprises françaises expérimentent la semaine de quatre jours sans baisse de salaire. Les premiers résultats sont plutôt encourageants : les salariés disent être moins stressés et avoir plus de temps pour leur famille, tandis que la productivité reste stable dans la plupart des cas. Les critiques soulignent toutefois que ce modèle ne convient pas à tous les secteurs, notamment à l\'hôpital, où le personnel manque déjà.',
      qs: [{ q: 'Comment sont les premiers résultats ?', o: ['Plutôt négatifs', 'Plutôt encourageants', 'Inconnus'], a: 1 }, { q: 'Que disent les critiques ?', o: ['C\'est trop cher partout.', 'Le modèle ne convient pas à tous les secteurs, comme l\'hôpital.', 'La productivité baisse toujours.'], a: 1 }] },
    { id: 'fr-t-c1-ia', l: 'C1', title: 'L\'intelligence artificielle au service du diagnostic', assess: 'reading', d: 'medical', text: 'Des algorithmes capables d\'interpréter une radiographie ou une lésion cutanée avec une précision comparable à celle de spécialistes chevronnés ne relèvent plus de la science-fiction. Leur intérêt en pratique clinique n\'en demeure pas moins discuté. D\'une part, nombre de ces systèmes ont été entraînés sur des bases de données qui ne reflètent qu\'imparfaitement la diversité des patients réels ; d\'autre part, la manière dont un modèle parvient à ses conclusions reste souvent opaque. S\'y ajoute la question, non résolue, de la responsabilité : qui répond d\'une erreur induite par une recommandation algorithmique ? Bien des sociétés savantes préconisent donc, pour l\'heure, de cantonner l\'IA au rôle de second avis plutôt que d\'en faire un substitut au jugement médical.',
      qs: [{ q: 'Que reproche le texte aux bases de données ?', o: ['Elles sont trop grandes.', 'Elles reflètent mal la diversité des patients.', 'Elles coûtent trop cher.'], a: 1 }, { q: 'Quel autre problème est mentionné ?', o: ['L\'opacité des modèles et la responsabilité', 'La lenteur des ordinateurs', 'Le refus des patients'], a: 0 }, { q: 'Que préconisent les sociétés savantes ?', o: ['Utiliser l\'IA partout dès maintenant', 'Limiter l\'IA au rôle de second avis', 'Interdire l\'IA'], a: 1 }] },
    { id: 'fr-t-c1-penurie', l: 'C1', title: 'La pénurie de soignants', assess: 'listening', text: 'La pénurie de soignants n\'est pas un phénomène nouveau, mais elle s\'est considérablement aggravée ces dernières années. Outre le vieillissement de la population, qui accroît les besoins en soins, les experts pointent surtout les conditions de travail : horaires décalés, charge de travail croissante et rémunération jugée insuffisante au regard des responsabilités. Le recrutement de soignants étrangers est certes présenté comme une partie de la solution, mais il ne saurait, selon eux, se substituer à des réformes structurelles.',
      qs: [{ q: 'Quelles causes sont citées ?', o: ['La numérisation et la bureaucratie', 'Le vieillissement de la population et les conditions de travail', 'Trop d\'hôpitaux'], a: 1 }, { q: 'Comment est jugé le recrutement de soignants étrangers ?', o: ['Comme la solution complète', 'Comme une partie de la solution, pas un substitut aux réformes', 'Comme inutile'], a: 1 }] },
    { id: 'fr-t-c2-mots', l: 'C2', title: 'Le poids des mots au chevet du patient', assess: 'reading', d: 'medical', text: 'Que les mots aient un effet relève de l\'évidence ; qu\'ils agissent parfois, lors d\'une consultation, à la manière d\'un médicament, voilà ce que les travaux sur l\'effet nocebo commencent à établir. Il apparaît que la seule énumération des effets indésirables possibles suffit, chez certains patients, à en favoriser la survenue. Faut-il en conclure qu\'il conviendrait de taire les risques ? Assurément non : l\'obligation d\'information n\'est pas négociable. Tout tient, en réalité, à la manière : énoncer les probabilités en chiffres absolus, ne pas craindre une formulation positive, ménager une place aux questions — autant de moyens de remplir son devoir sans attiser inutilement l\'angoisse.',
      qs: [{ q: 'Que montre l\'effet nocebo selon le texte ?', o: ['Que les placebos marchent toujours', 'Que l\'énumération des effets indésirables peut favoriser leur survenue', 'Que les patients ne comprennent pas les risques'], a: 1 }, { q: 'Quelle conclusion l\'auteur tire-t-il ?', o: ['Il faut taire les risques.', 'Tout dépend de la manière d\'informer.', 'L\'information est inutile.'], a: 1 }, { q: '"Relever de l\'évidence" signifie…', o: ['être évident', 'être nouveau', 'être faux'], a: 0 }] },
    { id: 'fr-t-c2-debat', l: 'C2', title: 'Extrait d\'un débat radiophonique', assess: 'listening', text: 'Alors, moi, ce que je voudrais dire, c\'est que la science, ces dernières années, elle a appris qu\'il fallait s\'expliquer — ce qui n\'était pas forcément le cas avant, hein. Mais bon, le hic, c\'est que la science, c\'est un processus, c\'est pas un catalogue de vérités toutes faites. Si je vous dis aujourd\'hui que les données penchent plutôt vers A et dans six mois plutôt vers B, c\'est pas un échec, c\'est exactement comme ça que ça doit marcher. Encore faut-il qu\'on accepte de l\'entendre.',
      qs: [{ q: 'Quel est "le hic" selon l\'intervenant ?', o: ['La science coûte trop cher.', 'La science est un processus, pas un catalogue de vérités.', 'Les scientifiques parlent trop bas.'], a: 1 }, { q: 'Comment juge-t-il les changements d\'avis ?', o: ['Comme un échec', 'Comme le fonctionnement normal de la science', 'Comme une manipulation'], a: 1 }] },
  ];

